final:
def age_at(born: int, now: int) -> int:
    """Whole years elapsed from the birth year `born` to the year `now`.

    `now` is supplied by the caller; this function never reads the clock.
    """
    return now - born


def test_age_at_same_year_is_zero() -> None:
    assert age_at(1990, 1990) == 0


def test_age_at_counts_whole_years() -> None:
    assert age_at(1990, 2024) == 34


def test_age_at_one_year_later() -> None:
    assert age_at(2000, 2001) == 1


def test_age_at_uses_given_year_not_clock() -> None:
    assert age_at(1900, 2000) == 100
    assert age_at(1900, 2100) == 200
